// Unify the Outlook trigger shape and the fixture webhook shape into one email envelope.
// PDF attachments land in $binary.attachment; everything else is text.
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const isWebhook = j.body !== undefined && j.headers !== undefined;
  const src = isWebhook ? j.body : j;
  const email = {
    email_id: src.email_id || src.id || `fixture-${Date.now()}`,
    source: isWebhook ? 'fixture' : 'outlook',
    from: src.from?.emailAddress?.address || src.from || '',
    subject: src.subject || '',
    received_at: src.receivedDateTime || src.received_at || new Date().toISOString(),
    body_text: typeof src.body === 'string' ? src.body : (src.body?.content || src.bodyPreview || ''),
    has_pdf: false,
  };
  const binary = {};
  if (src.attachment_base64) {
    binary.attachment = {
      data: src.attachment_base64, mimeType: 'application/pdf',
      fileName: src.attachment_name || 'attachment.pdf', fileExtension: 'pdf',
    };
    email.has_pdf = true;
  } else if (item.binary) {
    const key = Object.keys(item.binary).find(k => (item.binary[k].mimeType || '').includes('pdf'));
    if (key) { binary.attachment = item.binary[key]; email.has_pdf = true; }
  }
  out.push({ json: email, binary });
}
return out;

// One document per email: the body plus the attachment text when a PDF was present.
return $input.all().map(item => {
  const email = item.json.email_id ? item.json : $('NormalizeEmail').first().json;
  const pdfText = item.json.text || '';
  const document_text = [
    `EMAIL FROM: ${email.from}`,
    `SUBJECT: ${email.subject}`,
    `RECEIVED: ${email.received_at}`,
    '',
    '--- EMAIL BODY ---',
    email.body_text || '(empty)',
    pdfText ? `\n--- ATTACHMENT TEXT ---\n${pdfText}` : '',
  ].join('\n');
  return { json: { ...email, document_text, pdf_pages: item.json.numpages || 0 } };
});

