// Business validation rules over the AI extraction against the PO on record.
// Each rule: pass, weight, hard. A failed hard rule always routes to human review.
const AUTO_THRESHOLD = 0.90;      // score at or above this posts without a human
const PRICE_TOLERANCE_PCT = 2.0;  // per-line unit price drift allowed
const TOTAL_TOLERANCE_PCT = 1.0;  // document total vs PO total
const AI_WEIGHT = 0.30;           // share of the score taken from the model's self-reported confidence

const ex = $('ExtractPoFieldsWithAi').first().json.output || {};
const email = $('BuildDocumentText').first().json;
const po = $input.first().json || {};
const poFound = !!po.po_number;
const exLines = Array.isArray(ex.line_items) ? ex.line_items : [];
const poLines = Array.isArray(po.lines) ? po.lines : [];

const num = v => {
  const n = typeof v === 'number' ? v : parseFloat(String(v ?? '').replace(/[^0-9.\-]/g, ''));
  return Number.isFinite(n) ? n : null;
};
const pct = (a, b) => (b ? Math.abs(a - b) / Math.abs(b) * 100 : (a ? 100 : 0));
const cents = v => Math.round((num(v) ?? 0) * 100);
const norm = s => String(s ?? '').toLowerCase().replace(/[^a-z0-9]/g, '');

const rules = [];
const add = (id, name, pass, detail, weight, hard = false) => rules.push({ id, name, pass: !!pass, detail, weight, hard });

add('R1', 'PO exists in system of record', poFound,
  poFound ? `Found ${po.po_number}` : `No PO matching "${ex.po_number ?? ''}"`, 3, true);

const vendorMatch = poFound && (
  norm(ex.vendor_name).includes(norm(po.vendor_name).slice(0, 8)) ||
  norm(po.vendor_name).includes(norm(ex.vendor_name).slice(0, 8)) ||
  norm(email.from).includes(norm(po.email_domain).slice(0, 10)));
add('R2', 'Vendor matches PO vendor', vendorMatch,
  `Extracted "${ex.vendor_name ?? ''}", PO vendor "${po.vendor_name ?? ''}", sender ${email.from}`, 3, true);

add('R3', 'Currency matches PO', poFound && norm(ex.currency) === norm(po.currency),
  `Extracted ${ex.currency ?? '?'}, PO ${po.currency ?? '?'}`, 2);

add('R4', 'Line count matches PO', poFound && exLines.length === poLines.length,
  `${exLines.length} extracted vs ${poLines.length} on PO`, 1);

let qtyOk = true, priceOk = true, skuOk = true;
const notes = { sku: [], qty: [], price: [] };
for (const l of exLines) {
  const m = poLines.find(p => norm(p.sku) === norm(l.sku)) || poLines.find(p => Number(p.line_no) === Number(l.line_no));
  if (!m) { skuOk = false; notes.sku.push(`${l.sku ?? 'line ' + l.line_no}: not on PO`); continue; }
  const q = num(l.quantity), oq = num(m.quantity);
  if (q !== null && oq !== null && q > oq) { qtyOk = false; notes.qty.push(`${m.sku}: qty ${q} > ordered ${oq}`); }
  const p = num(l.unit_price), op = num(m.unit_price);
  if (p !== null && op !== null && pct(p, op) > PRICE_TOLERANCE_PCT) {
    priceOk = false; notes.price.push(`${m.sku}: price ${p} vs PO ${op} (${pct(p, op).toFixed(1)}%)`);
  }
}
add('R5', 'Every line maps to a PO line', poFound && skuOk, notes.sku.join('; ') || 'All lines matched', 2);
add('R6', 'Quantities within ordered quantity', poFound && qtyOk, notes.qty.join('; ') || 'OK', 2);
add('R7', `Unit prices within ${PRICE_TOLERANCE_PCT}% of PO`, poFound && priceOk, notes.price.join('; ') || 'OK', 3);

const exTotal = num(ex.total_amount);
const sumLines = exLines.reduce((s, l) => s + (num(l.line_total) ?? (num(l.quantity) ?? 0) * (num(l.unit_price) ?? 0)), 0);
add('R8', 'Document total equals sum of lines', exTotal !== null && Math.abs(cents(exTotal) - cents(sumLines)) <= 100,
  `Total ${exTotal} vs lines ${sumLines.toFixed(2)}`, 1);
add('R9', `Document total within ${TOTAL_TOLERANCE_PCT}% of PO total`,
  poFound && exTotal !== null && pct(exTotal, num(po.total_amount)) <= TOTAL_TOLERANCE_PCT,
  `Total ${exTotal} vs PO ${po.total_amount ?? '?'}`, 2);

const wTotal = rules.reduce((s, r) => s + r.weight, 0);
const wPass = rules.filter(r => r.pass).reduce((s, r) => s + r.weight, 0);
const rulesScore = wTotal ? wPass / wTotal : 0;
const aiConf = Math.min(1, Math.max(0, num(ex.extraction_confidence) ?? 0.5));
const score = Math.round(((1 - AI_WEIGHT) * rulesScore + AI_WEIGHT * aiConf) * 1000) / 1000;
const hardFail = rules.some(r => r.hard && !r.pass);
const decision = (!hardFail && score >= AUTO_THRESHOLD) ? 'auto' : 'review';

return [{ json: {
  email, extracted: ex, po: poFound ? po : null,
  rule_results: rules,
  rules_score: Math.round(rulesScore * 1000) / 1000,
  ai_confidence: aiConf, score, threshold: AUTO_THRESHOLD, hard_fail: hardFail,
  decision, status: decision === 'auto' ? 'auto_approved' : 'pending_review',
  failed_rules: rules.filter(r => !r.pass).map(r => `${r.id} ${r.name}: ${r.detail}`),
}}];

