// ORDERS05 IDoc from the validated extraction, plus the row for the Snowflake landing table.
const ctx = $('ApplyValidationRules').first().json;
const recId = $('LogReconciliation').first().json.id;
const ex = ctx.extracted, po = ctx.po || {}, lines = po.lines || [];
const esc = s => String(s ?? '').replace(/[<>&'"]/g, c => ({ '<': '&lt;', '>': '&gt;', '&': '&amp;', "'": '&apos;', '"': '&quot;' }[c]));
const d = v => String(v ?? '').slice(0, 10).replace(/-/g, '');
const now = new Date().toISOString();
const d8 = d(now), t6 = now.slice(11, 19).replace(/:/g, '');
const idocNumber = `${d8}${t6}${String(recId).padStart(6, '0')}`;
const msgType = { order_confirmation: 'ORDRSP', invoice: 'INVOIC', shipping_notice: 'DESADV' }[ex.document_type] || 'ORDRSP';

const segs = (ex.line_items || []).map((l, i) => {
  const m = lines.find(p => String(p.sku).toLowerCase() === String(l.sku ?? '').toLowerCase()) || lines[i] || {};
  const promised = l.promised_date ? `<E1EDP20 SEGMENT="1"><WMENG>${esc(l.quantity)}</WMENG><EDATU>${d(l.promised_date)}</EDATU></E1EDP20>` : '';
  return [
    '    <E1EDP01 SEGMENT="1">',
    `      <POSEX>${String(m.line_no ?? l.line_no ?? i + 1).padStart(6, '0')}</POSEX>`,
    `      <MENGE>${esc(l.quantity)}</MENGE><MENEE>EA</MENEE>`,
    `      <VPREI>${esc(l.unit_price)}</VPREI><NETWR>${esc(l.line_total)}</NETWR>`,
    `      <E1EDP19 SEGMENT="1"><QUALF>002</QUALF><IDTLF>${esc(m.sku ?? l.sku)}</IDTLF><KTEXT>${esc(l.description ?? m.description)}</KTEXT></E1EDP19>`,
    promised ? `      ${promised}` : null,
    '    </E1EDP01>',
  ].filter(Boolean).join('\n');
}).join('\n');

const xml = `<?xml version="1.0" encoding="UTF-8"?>
<ORDERS05>
  <IDOC BEGIN="1">
    <EDI_DC40 SEGMENT="1">
      <TABNAM>EDI_DC40</TABNAM><DOCNUM>${idocNumber}</DOCNUM><DIRECT>2</DIRECT>
      <IDOCTYP>ORDERS05</IDOCTYP><MESTYP>${msgType}</MESTYP>
      <SNDPOR>N8N_POC</SNDPOR><SNDPRT>LS</SNDPRT><SNDPRN>N8N_OM_POC</SNDPRN>
      <RCVPOR>SAPERP</RCVPOR><RCVPRT>LS</RCVPRT><RCVPRN>OM_ERP</RCVPRN>
      <CREDAT>${d8}</CREDAT><CRETIM>${t6}</CRETIM>
    </EDI_DC40>
    <E1EDK01 SEGMENT="1"><CURCY>${esc(ex.currency || po.currency)}</CURCY><BELNR>${esc(ex.vendor_reference)}</BELNR></E1EDK01>
    <E1EDK02 SEGMENT="1"><QUALF>001</QUALF><BELNR>${esc(po.po_number)}</BELNR><DATUM>${d(po.order_date)}</DATUM></E1EDK02>
    <E1EDK02 SEGMENT="1"><QUALF>002</QUALF><BELNR>${esc(ex.vendor_reference)}</BELNR><DATUM>${d(ex.document_date)}</DATUM></E1EDK02>
    <E1EDKA1 SEGMENT="1"><PARVW>LF</PARVW><PARTN>${esc(po.vendor_id)}</PARTN><NAME1>${esc(po.vendor_name)}</NAME1></E1EDKA1>
${segs}
    <E1EDS01 SEGMENT="1"><SUMID>002</SUMID><SUMME>${esc(ex.total_amount)}</SUMME><SUNIT>${esc(ex.currency || po.currency)}</SUNIT></E1EDS01>
  </IDOC>
</ORDERS05>`;

return [{ json: {
  reconciliation_id: recId, idoc_number: idocNumber, idoc_type: 'ORDERS05', message_type: msgType, xml,
  snowflake_row: {
    reconciliation_id: recId, po_number: po.po_number, vendor_name: po.vendor_name,
    document_type: ex.document_type, currency: ex.currency || po.currency, total_amount: ex.total_amount,
    line_count: (ex.line_items || []).length, ai_confidence: ctx.ai_confidence, score: ctx.score,
    decision: ctx.decision, idoc_number: idocNumber,
  },
}}];

parameters.query:
insert into om_poc.idoc_outbox (reconciliation_id, idoc_number, idoc_type, xml)
values ($1, $2, $3, $4)
returning id, idoc_number, status;

update om_poc.reconciliations set status = 'posted', idoc_number = $2, reviewer_decision = $3, updated_at = now()
where id = $1
returning id, po_number, status, idoc_number;

update om_poc.reconciliations set status = 'rejected', reviewer_decision = 'reject', updated_at = now()
where id = $1
returning id, po_number, status, null::text as idoc_number;

